import{_ as t,o as d,c as s,ak as r}from"./chunks/framework.sV-XtlWr.js";const p=JSON.parse(`{"title":"MCP tools","description":"Every tool the dashboard's MCP server serves, by module, with the capability that removes it when declined, generated from the tool catalog.","frontmatter":{"title":"MCP tools","description":"Every tool the dashboard's MCP server serves, by module, with the capability that removes it when declined, generated from the tool catalog.","lang":"en-US","editLink":false,"head":[["link",{"rel":"canonical","href":"https://piwitests.dev/reference/mcp-tools.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/reference/mcp-tools.html"}],["meta",{"property":"og:title","content":"MCP tools | Piwi Dashboard"}],["meta",{"property":"og:description","content":"Every tool the dashboard's MCP server serves, by module, with the capability that removes it when declined, generated from the tool catalog."}]]},"headers":[],"relativePath":"reference/mcp-tools.md","filePath":"reference/mcp-tools.md","lastUpdated":null}`),o={name:"reference/mcp-tools.md"};function a(i,e,n,c,l,h){return d(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="mcp-tools" tabindex="-1">MCP tools <a class="header-anchor" href="#mcp-tools" aria-label="Permalink to &quot;MCP tools&quot;">​</a></h1><p>The <a href="/features/mcp.html">MCP server</a> serves 65 tools. Each belongs to one <strong>module</strong>, the groups the Setup page asks about, and <code>?modules=</code> on the MCP URL narrows the list to some of them. A tool with a <strong>capability</strong> leaves <code>tools/list</code> and <code>tools/call</code> when an administrator declines that capability for the instance; a tool without one is always served.</p><p>Each description here is the first sentence of the one the server sends to the agent. The <strong>MCP server</strong> page of the dashboard (<code>/mcp</code>) lists the same catalog, with the tools of declined capabilities left out.</p><h2 id="core" tabindex="-1">Core <a class="header-anchor" href="#core" aria-label="Permalink to &quot;Core&quot;">​</a></h2><p>40 of the 65 tools. Setup offers this module as <strong>See why tests fail</strong>: run history, traces, failure clusters and flaky scoring.</p><table tabindex="0"><thead><tr><th>Tool</th><th>What it returns or does</th><th>Capability</th></tr></thead><tbody><tr><td><code id="list_projects">list_projects</code></td><td>List all projects with stats: total runs, test cases, latest run status and branch.</td><td>none</td></tr><tr><td><code id="get_project">get_project</code></td><td>Get project details and its recent test runs with pass/fail counts.</td><td>none</td></tr><tr><td><code id="list_runs">list_runs</code></td><td>List test runs for a project with filters.</td><td>none</td></tr><tr><td><code id="get_run">get_run</code></td><td>Get a test run summary plus its test cases (paginated), with status, truncated error text, and failure cluster IDs.</td><td>none</td></tr><tr><td><code id="list_failed_cases">list_failed_cases</code></td><td>List failed and timed-out test cases across recent runs for a project.</td><td>none</td></tr><tr><td><code id="list_flaky_tests">list_flaky_tests</code></td><td>List flaky tests for a project with flakiness scores.</td><td>none</td></tr><tr><td><code id="get_test_case">get_test_case</code></td><td>Get test case details including aggregated pass/fail stats, flakiness metrics, and recent executions (paginated).</td><td>none</td></tr><tr><td><code id="list_clusters">list_clusters</code></td><td>List failure clusters for a project.</td><td>none</td></tr><tr><td><code id="get_cluster">get_cluster</code></td><td>Get full details for a failure cluster including all affected test cases, a compact diagnosis summary, and locator healing suggestions for up to 5 affected cases.</td><td>none</td></tr><tr><td><code id="get_fix_plan">get_fix_plan</code></td><td>Everything needed to fix one failure cluster, in a single answer: the diagnosis and its validated patch, ranked locator replacements each with the exact file and line and a ready-to-apply <code>edit</code> (the rewritten line plus a unified diff <code>git apply</code> accepts), the failing tests, the owning team, the command that verifies the work, a <code>reproduce</code> recipe (checkout, pinned install, browser install and the exact test command as <code>{ bash, powershell }</code> steps), and a <code>bisect</code> script (<code>git bisect</code> between the last green and the failing commit, or <code>available: false</code> with a reason).</td><td>none</td></tr><tr><td><code id="get_test_case_context">get_test_case_context</code></td><td>Get the AI evidence context for a specific test-run-case (execution scope).</td><td>none</td></tr><tr><td><code id="get_case_screenshots">get_case_screenshots</code></td><td>Get screenshots for a test-run-case.</td><td>none</td></tr><tr><td><code id="get_cluster_context">get_cluster_context</code></td><td>Get the full AI evidence context for a failure cluster, the same data sent to the diagnosis AI.</td><td>none</td></tr><tr><td><code id="search_test_cases">search_test_cases</code></td><td>Search test cases by title or file path within a project.</td><td>none</td></tr><tr><td><code id="get_test_run_case">get_test_run_case</code></td><td>Get a single test-run-case execution record with a one-line failure headline, the full (untruncated) error text plus steps, console logs, web vitals, and ARIA snapshot.</td><td>none</td></tr><tr><td><code id="list_recent_activity">list_recent_activity</code></td><td>List the most recent test runs across all projects.</td><td>none</td></tr><tr><td><code id="get_repo_commits">get_repo_commits</code></td><td>List recent commits for a project&#39;s repository.</td><td><a href="/guide/source-control.html"><code>scm</code></a></td></tr><tr><td><code id="get_repo_diff">get_repo_diff</code></td><td>Get the diff (changed files with patches) for a single commit in a project&#39;s repository.</td><td><a href="/guide/source-control.html"><code>scm</code></a></td></tr><tr><td><code id="get_run_insights">get_run_insights</code></td><td>Compare a run to its baseline: pass-rate delta, new regressions, recurrences, recovered tests, new flaky tests, biggest perf improvements/regressions, worker imbalance, and newly opened clusters.</td><td>none</td></tr><tr><td><code id="get_spec_health">get_spec_health</code></td><td>Per-spec-file health for a project: pass rate, flaky rate, failure count, execution count (<code>testCount</code>), and average duration grouped by spec-file prefix over the last N days.</td><td>none</td></tr><tr><td><code id="get_slow_tests">get_slow_tests</code></td><td>Slowest test cases in a project by average duration, with max/min and trend direction across recent runs.</td><td><a href="/guide/capture-fixtures.html"><code>fixtures</code></a></td></tr><tr><td><code id="get_performance_trend">get_performance_trend</code></td><td>Time series of run duration, average test duration, and p90 test duration for a project.</td><td><a href="/guide/capture-fixtures.html"><code>fixtures</code></a></td></tr><tr><td><code id="get_test_stability_trend">get_test_stability_trend</code></td><td>Time-series stability for a single test case: flaky rate, pass rate, and average duration in UTC time buckets (about 31 of them) over the last N days.</td><td>none</td></tr><tr><td><code id="get_network_requests">get_network_requests</code></td><td>A run&#39;s network requests aggregated by method + normalized route, sorted by average duration: request count, average, p90 and max duration, error rate, and the tests that made them.</td><td><a href="/guide/capture-fixtures.html"><code>fixtures</code></a></td></tr><tr><td><code id="get_failure_groups">get_failure_groups</code></td><td>One run&#39;s failures grouped by failure cluster, with per-group affected cases and worker correlation.</td><td>none</td></tr><tr><td><code id="search">search</code></td><td>Global search across all in-scope projects, runs (by label or numeric id), and test cases (by title).</td><td>none</td></tr><tr><td><code id="list_case_traces">list_case_traces</code></td><td>List Playwright trace files for a test-run-case, with a download path for each.</td><td>none</td></tr><tr><td><code id="list_tags">list_tags</code></td><td>List every tag defined on this instance (id, text, color).</td><td><a href="/guide/reporter.html"><code>tags</code></a></td></tr><tr><td><code id="list_open_clusters">list_open_clusters</code></td><td>Open failure clusters across all in-scope projects, ranked by occurrences, a cross-project triage queue, the same one the dashboard failure inbox shows.</td><td>none</td></tr><tr><td><code id="get_instance_stats">get_instance_stats</code></td><td>Instance-wide counts (projects, runs, test cases, executions, files) and total storage size.</td><td>none</td></tr><tr><td><code id="explain_failure">explain_failure</code></td><td>One-call evidence bundle for a single failing execution: a one-line headline, the error, steps, console, ARIA snapshot, the recommended locator fix, the structural page diff against the last green sample, a screenshot count, and the AI diagnosis context.</td><td>none</td></tr><tr><td><code id="set_cluster_status">set_cluster_status</code></td><td>Triage a failure cluster: set its status to open, resolved, or ignored with an optional note.</td><td>none</td></tr><tr><td><code id="set_cluster_base_commit">set_cluster_base_commit</code></td><td>Pin the baseline commit SHA a cluster uses for its SCM-diff diagnosis context, so &quot;what changed since green&quot; is accurate.</td><td>none</td></tr><tr><td><code id="describe_piwi">describe_piwi</code></td><td>Piwi itself, from its own documentation: what it is and is not, every piece of its ecosystem, how to set it up and configure it, which option fits which need, what this instance has switched on, and where to report a bug or suggest an improvement.</td><td>none</td></tr><tr><td><code id="get_change_coverage">get_change_coverage</code></td><td>Change coverage for a pull request: the files a change touched joined to the tests that observably reach them, grouped by ticket, with the uncovered files that need a scenario.</td><td><a href="/guide/source-control.html"><code>scm</code></a></td></tr><tr><td><code id="get_release_notes">get_release_notes</code></td><td>What changed in each Piwi release, from the changelog shipped with this server, so it ends at the running version; newer releases are on GitHub.</td><td>none</td></tr><tr><td><code id="get_metric_trend">get_metric_trend</code></td><td>One metric from the metric catalog over a scope: its value and change against the comparison period, its definition, and its series bucketed over the period with the comparison period aligned bucket for bucket.</td><td>none</td></tr><tr><td><code id="list_dashboards">list_dashboards</code></td><td>Every dashboard you can open: the built-in ones (overview is the analytics page; executive, engineering and gaps-digest are the report dashboards) and the saved dashboards shared with everyone or yours, each with its id, name, description, owner, visibility and widget count.</td><td>none</td></tr><tr><td><code id="get_dashboard">get_dashboard</code></td><td>One dashboard with every widget’s data, the JSON the page renders, band by band.</td><td>none</td></tr><tr><td><code id="compare_periods">compare_periods</code></td><td>The headline metrics of one scope over two periods chosen freely, e.g. this sprint against the last one, or August against July: each metric over <code>a</code>, with <code>b</code> as its previous value and the change.</td><td>none</td></tr></tbody></table><h2 id="workflow" tabindex="-1">Workflow <a class="header-anchor" href="#workflow" aria-label="Permalink to &quot;Workflow&quot;">​</a></h2><p>20 of the 65 tools. Setup offers this module as <strong>Triage as a team</strong>: notifications, quarantine, pull-request feedback, issue tracking and the Test Map.</p><table tabindex="0"><thead><tr><th>Tool</th><th>What it returns or does</th><th>Capability</th></tr></thead><tbody><tr><td><code id="get_flake_profile">get_flake_profile</code></td><td>The suspects of a flaky test, read from its last 30 days (at most 200 attempts): the slow or failed routes, the tests running alongside or just before it on the same worker, the load and the browser project its failures share and its passes do not.</td><td><a href="/features/flaky-tests.html"><code>flake-lab</code></a></td></tr><tr><td><code id="plan_flake_experiment">plan_flake_experiment</code></td><td>The Flake Lab plan for a flaky test, for an agent that runs the lab itself: the <code>piwi flake</code> and <code>piwi flake verify</code> commands to run from the project root, the control arm and one arm per suspect (most likely first) with the conditions each applies (delay or fail a route, throttle the CPU, run another test alongside or first, pin a project), the runs and the early stop, the error signatures a failure must match, and an estimate from the test’s median duration.</td><td><a href="/features/flaky-tests.html"><code>flake-lab</code></a></td></tr><tr><td><code id="list_resource_findings">list_resource_findings</code></td><td>A project’s resource findings across runs, the most recently seen first: browsers, contexts, pages and API contexts left open past the test or describe block that opened them (leaked), pages opened and never used (idle), pages, listeners or route handlers growing on a long-lived page (piling), Node servers or file watchers a test left running in its worker (handle), and leaks counted from steps without the capture fixtures (probable).</td><td><a href="/features/resource-leaks.html"><code>resources</code></a></td></tr><tr><td><code id="get_resource_profile">get_resource_profile</code></td><td>What one run cost and left open, from its reporters’ resource reports (one per shard): the findings, each with whether its base branch (the pull request’s target, else the default branch) had shown it before (<code>isNew</code>); the machine each shard ran on (cores, memory, how busy its CPUs were, the share of time a task waited for a CPU, CPU time by process role, peak memory and the largest process, disk); the busiest open pages per worker; and the costliest tests by the CPU of their worker and browser processes, with the pages each found already open.</td><td><a href="/features/resource-leaks.html"><code>resources</code></a></td></tr><tr><td><code id="list_links">list_links</code></td><td>List external entity links (Jira, GitHub PR/issue, etc.) attached to a run, test-run-case, test case, or failure cluster, with provider and unfurled status.</td><td><a href="/features/issue-tracking.html"><code>integrations</code></a></td></tr><tr><td><code id="create_issue">create_issue</code></td><td>File a Jira issue from a failure cluster or a failing execution, with the fix plan as its body, the same ticket the dashboard&#39;s Create issue button produces.</td><td><a href="/features/issue-tracking.html"><code>integrations</code></a></td></tr><tr><td><code id="get_project_test_catalog">get_project_test_catalog</code></td><td>The full test-case catalog for a project with aggregated pass/fail/flaky counts, average duration, and last status per test.</td><td>none</td></tr><tr><td><code id="list_selections">list_selections</code></td><td>A project&#39;s saved test selections plus the built-in ones (failed, quarantine-free).</td><td>none</td></tr><tr><td><code id="resolve_selection">resolve_selection</code></td><td>Resolve a saved (or built-in) selection to the tests it currently matches and a ready-to-run <code>playwright test</code> command.</td><td>none</td></tr><tr><td><code id="preview_selection">preview_selection</code></td><td>Resolve an ad-hoc selection definition without saving it, the dry-run behind the builder.</td><td>none</td></tr><tr><td><code id="suggest_selections">suggest_selections</code></td><td>Suggest tags and a smoke suite for a project from observed history (suggest-only, with evidence).</td><td>none</td></tr><tr><td><code id="analyze_selections">analyze_selections</code></td><td>Health and drift for a project&#39;s selections.</td><td>none</td></tr><tr><td><code id="create_test_function">create_test_function</code></td><td>Register a page-object method or helper in a project&#39;s test-function catalog, so the Piwi Picker browser extension (and its recorder) can match a live page or a recorded session against it and substitute a call to your own code instead of raw locator lines.</td><td>none</td></tr><tr><td><code id="list_scenario_gaps">list_scenario_gaps</code></td><td>Ranked scenario gaps for a project: tests that do not exist yet, each with its class (blind-spot, false-comfort, fragile), evidence lines and exposure score.</td><td><a href="/features/scenario-gaps.html"><code>test-map</code></a></td></tr><tr><td><code id="draft_scenario">draft_scenario</code></td><td>A deterministic test skeleton for a scenario gap: a title from the gap, piwi: annotations from the nearest test, the graph path from a reached page to the gap as the step list, catalog page-object methods where they match, and a TODO assertion naming what to check.</td><td><a href="/features/scenario-gaps.html"><code>test-map</code></a></td></tr><tr><td><code id="get_feature_graph">get_feature_graph</code></td><td>The feature-graph neighborhood around a node: walk the typed graph (tests, pages, controls, routes, handlers, dependencies) outward from <code>node</code> to <code>depth</code> hops (capped at six), returning each node with its gap class and the tests that reach it, and the edges between them.</td><td><a href="/features/scenario-gaps.html"><code>test-map</code></a></td></tr><tr><td><code id="get_quality_report">get_quality_report</code></td><td>A quality report as its bundle: a built-in dashboard (executive: a rule-based verdict, headline numbers, the pass-rate trend, what changed, what is being done and the risks; engineering adds flaky tests, clusters, CI time, detail and scenario gaps; team is engineering for one owner and needs <code>owners</code>; gaps-digest is the Test Map’s weekly digest; overview is the analytics page) rendered over a scope, every string already formatted.</td><td><a href="/features/quality-reports.html"><code>quality-reports</code></a></td></tr><tr><td><code id="list_bug_reports">list_bug_reports</code></td><td>A project’s bug reports, newest first: bugs reported from Piwi Picker with their steps, the expected result and evidence.</td><td><a href="/features/bug-reports.html"><code>bug-reports</code></a></td></tr><tr><td><code id="get_bug_report">get_bug_report</code></td><td>One bug report: its steps in words, each expected assertion with the value the page showed instead, the steps document itself (to replay or render), the evidence (console errors, failed requests with their status, the page outline), the reproductions recorded since, and the test that reproduces it.</td><td><a href="/features/bug-reports.html"><code>bug-reports</code></a></td></tr><tr><td><code id="render_steps">render_steps</code></td><td>Render a steps document as a Playwright spec with the converter every Piwi surface uses.</td><td><a href="/features/bug-reports.html"><code>bug-reports</code></a></td></tr></tbody></table><h2 id="healing" tabindex="-1">Healing <a class="header-anchor" href="#healing" aria-label="Permalink to &quot;Healing&quot;">​</a></h2><p>2 of the 65 tools. Setup offers this module as <strong>Fix faster</strong>: locator healing and auto-heal pull requests.</p><table tabindex="0"><thead><tr><th>Tool</th><th>What it returns or does</th><th>Capability</th></tr></thead><tbody><tr><td><code id="get_locator_healing">get_locator_healing</code></td><td>Ranked alternative locators for a failing test-run-case: the failing locator, the recommended durable fix, and the full alternative lists (from prior success, element match, and ARIA snapshot).</td><td><a href="/features/locator-healing.html"><code>locator-healing</code></a></td></tr><tr><td><code id="predict_locator_breaks">predict_locator_breaks</code></td><td>Which of the project&#39;s test locators a change breaks, before any test runs.</td><td>none</td></tr></tbody></table><h2 id="agents" tabindex="-1">Agents <a class="header-anchor" href="#agents" aria-label="Permalink to &quot;Agents&quot;">​</a></h2><p>3 of the 65 tools. Setup offers this module as <strong>Let agents in</strong>: AI diagnosis over your real diff.</p><table tabindex="0"><thead><tr><th>Tool</th><th>What it returns or does</th><th>Capability</th></tr></thead><tbody><tr><td><code id="get_cluster_diagnosis">get_cluster_diagnosis</code></td><td>Get the stored AI diagnosis for a failure cluster.</td><td><a href="/guide/ai-provider.html"><code>ai</code></a></td></tr><tr><td><code id="submit_diagnosis_feedback">submit_diagnosis_feedback</code></td><td>Record thumbs up/down feedback on a stored diagnosis, with an optional note.</td><td><a href="/guide/ai-provider.html"><code>ai</code></a></td></tr><tr><td><code id="run_cluster_diagnosis">run_cluster_diagnosis</code></td><td>Trigger an AI diagnosis for a failure cluster and return the result (category, confidence, root cause, suggested fix).</td><td><a href="/guide/ai-provider.html"><code>ai</code></a></td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/features/mcp.html">MCP server</a>: authentication, client setup and prompts</li><li><a href="/features/agent-skills.html">Agent skills</a>: the workflows that call these tools</li><li><a href="/operate/capabilities.html">Choose what you use</a>: declining a capability or a module</li></ul>',17)])])}const g=t(o,[["render",a]]);export{p as __pageData,g as default};
